cat > /app/generate_deck.js <<'JS'
const pptxgen = require('pptxgenjs');
const fs = require('fs');
const path = require('path');

const pptx = new pptxgen();
pptx.layout = 'LAYOUT_16X9';
pptx.author = 'OpenAI';
pptx.company = 'OpenAI';
pptx.subject = 'KnowSelf: Agentic Knowledgeable Self-Awareness for LLM-Based Agents';
pptx.title = 'KnowSelf: Teaching LLM Agents When to Think, Reflect, or Seek Knowledge';
pptx.lang = 'en-US';
pptx.theme = {
  headFontFace: 'Aptos Display',
  bodyFontFace: 'Aptos',
  lang: 'en-US'
};
pptx.margin = 0;
pptx.defineLayout({ name: 'CUSTOM_WIDE', width: 10, height: 5.625 });
pptx.layout = 'CUSTOM_WIDE';

const C = {
  bg: 'F8FAFC',
  ink: '0F172A',
  muted: '64748B',
  line: 'CBD5E1',
  navy: '0B1220',
  blue: '2563EB',
  cyan: '06B6D4',
  teal: '14B8A6',
  amber: 'F59E0B',
  orange: 'EA580C',
  red: 'DC2626',
  green: '16A34A',
  purple: '7C3AED',
  lilac: 'EDE9FE',
  blueSoft: 'DBEAFE',
  cyanSoft: 'CFFAFE',
  tealSoft: 'CCFBF1',
  amberSoft: 'FEF3C7',
  redSoft: 'FEE2E2',
  greenSoft: 'DCFCE7',
  white: 'FFFFFF',
  gold: 'D4AF37',
  grey: 'E2E8F0',
  grey2: 'F1F5F9'
};

const W = 10;
const H = 5.625;
const assets = '/app/benchmark/assets';
const fig1 = path.join(assets, 'figure_1.jpg');
const fig3 = path.join(assets, 'figure_3.jpg');

function addBg(slide) {
  slide.background = { color: C.bg };
  slide.addShape(pptx.ShapeType.rect, { x: 0, y: 0, w: W, h: H, fill: { color: C.bg }, line: { color: C.bg } });
  slide.addShape(pptx.ShapeType.rect, { x: 0, y: 0, w: 0.12, h: H, fill: { color: C.blue }, line: { color: C.blue } });
}
function addTitle(slide, title, eyebrow) {
  if (eyebrow) slide.addText(eyebrow.toUpperCase(), { x: 0.45, y: 0.22, w: 6.4, h: 0.22, fontFace: 'Aptos', fontSize: 7.5, bold: true, color: C.blue, charSpace: 0.9, margin: 0 });
  slide.addText(title, { x: 0.45, y: eyebrow ? 0.47 : 0.25, w: 8.65, h: 0.58, fontFace: 'Aptos Display', fontSize: 19.5, bold: true, color: C.ink, fit: 'shrink', margin: 0 });
}
function footer(slide, n, note='KnowSelf · arxiv.org/abs/2504.03553') {
  slide.addText(note, { x: 0.45, y: 5.28, w: 6.5, h: 0.14, fontSize: 6.5, color: C.muted, margin: 0 });
  slide.addShape(pptx.ShapeType.roundRect, { x: 9.25, y: 5.13, w: 0.42, h: 0.26, rectRadius: 0.04, fill: { color: C.ink }, line: { color: C.ink } });
  slide.addText(String(n).padStart(2,'0'), { x: 9.25, y: 5.18, w: 0.42, h: 0.08, align: 'center', fontSize: 6.5, bold: true, color: C.white, margin: 0 });
}
function card(slide, x, y, w, h, opts={}) {
  slide.addShape(pptx.ShapeType.roundRect, {
    x, y, w, h,
    rectRadius: 0.06,
    fill: { color: opts.fill || C.white, transparency: opts.transparency || 0 },
    line: { color: opts.line || C.grey, transparency: opts.lineTrans || 0, width: opts.lineWidth || 1 },
    shadow: opts.shadow === false ? undefined : { type: 'outer', color: '000000', opacity: 0.08, blur: 1, offset: 1, angle: 45 }
  });
}
function pill(slide, txt, x, y, w, fill, color=C.ink) {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h: 0.24, rectRadius: 0.08, fill: { color: fill }, line: { color: fill } });
  slide.addText(txt, { x, y: y+0.055, w, h: 0.08, align: 'center', fontSize: 6.5, bold: true, color, margin: 0 });
}
function bulletList(slide, items, x, y, w, opts={}) {
  const fs = opts.fontSize || 9.5;
  const gap = opts.gap || 0.36;
  items.forEach((it, idx) => {
    const yy = y + idx*gap;
    slide.addShape(pptx.ShapeType.ellipse, { x, y: yy+0.05, w: 0.08, h: 0.08, fill: { color: opts.dot || C.blue }, line: { color: opts.dot || C.blue } });
    slide.addText(it, { x: x+0.16, y: yy, w, h: opts.h || 0.22, fontSize: fs, color: opts.color || C.ink, breakLine: false, fit: 'shrink', margin: 0 });
  });
}
function arrow(slide, x1, y1, x2, y2, color=C.muted, width=1.5) {
  slide.addShape(pptx.ShapeType.line, { x: x1, y: y1, w: x2-x1, h: y2-y1, line: { color, width, beginArrowType: 'none', endArrowType: 'triangle' } });
}
function addMetric(slide, label, value, x, y, w, color, sub) {
  card(slide, x, y, w, 0.78, { fill: C.white, line: C.grey });
  slide.addText(value, { x: x+0.12, y: y+0.12, w: w-0.24, h: 0.22, fontSize: 16, bold: true, color, margin: 0, fit: 'shrink' });
  slide.addText(label, { x: x+0.12, y: y+0.42, w: w-0.24, h: 0.12, fontSize: 6.5, bold: true, color: C.ink, margin: 0 });
  if (sub) slide.addText(sub, { x: x+0.12, y: y+0.58, w: w-0.24, h: 0.1, fontSize: 5.8, color: C.muted, margin: 0 });
}
function imageCard(slide, img, x, y, w, h, caption) {
  card(slide, x, y, w, h, { fill: C.white, line: C.grey });
  slide.addImage({ path: img, x: x+0.08, y: y+0.12, w: w-0.16, h: h-0.43, sizingCrop: false });
  slide.addText(caption, { x: x+0.12, y: y+h-0.24, w: w-0.24, h: 0.1, fontSize: 5.8, color: C.muted, align: 'center', margin: 0 });
}
function bar(slide, label, val, know, x, y, w, color, max=100) {
  const allW = w * (val/max);
  const knowW = w * (know/max);
  slide.addText(label, { x, y: y-0.02, w: 1.45, h: 0.12, fontSize: 6.4, bold: true, color: C.ink, fit: 'shrink', margin: 0 });
  slide.addShape(pptx.ShapeType.roundRect, { x: x+1.5, y, w, h: 0.13, rectRadius: 0.04, fill: { color: C.grey }, line: { color: C.grey } });
  slide.addShape(pptx.ShapeType.roundRect, { x: x+1.5, y, w: allW, h: 0.13, rectRadius: 0.04, fill: { color }, line: { color } });
  slide.addText(val.toFixed(2), { x: x+1.55+w, y: y-0.02, w: 0.43, h: 0.12, fontSize: 6.2, color: C.ink, margin: 0 });
  slide.addShape(pptx.ShapeType.roundRect, { x: x+1.5, y: y+0.20, w, h: 0.10, rectRadius: 0.03, fill: { color: C.grey2 }, line: { color: C.grey2 } });
  slide.addShape(pptx.ShapeType.roundRect, { x: x+1.5, y: y+0.20, w: knowW, h: 0.10, rectRadius: 0.03, fill: { color: C.amber }, line: { color: C.amber } });
  slide.addText(`${know}%`, { x: x+1.55+w, y: y+0.17, w: 0.43, h: 0.12, fontSize: 5.8, color: C.muted, margin: 0 });
}

// Slide 1
{
  const s = pptx.addSlide();
  s.background = { color: C.navy };
  s.addShape(pptx.ShapeType.rect, { x:0, y:0, w:W, h:H, fill:{color:C.navy}, line:{color:C.navy} });
  s.addShape(pptx.ShapeType.arc, { x:6.15, y:-0.85, w:4.4, h:4.4, line:{color:C.blue, transparency:30, width:2}, adjustPoint:0.22, rotate:20 });
  s.addShape(pptx.ShapeType.arc, { x:6.95, y:1.48, w:2.7, h:2.7, line:{color:C.cyan, transparency:20, width:1.5}, rotate:200 });
  s.addShape(pptx.ShapeType.rect, { x:0.58, y:0.52, w:1.18, h:0.06, fill:{color:C.gold}, line:{color:C.gold} });
  pill(s, 'LLM-BASED AGENTS · PLANNING · SELF-AWARENESS', 0.62, 0.88, 2.85, C.blueSoft, C.blue);
  s.addText('KnowSelf', { x:0.58, y:1.38, w:4.1, h:0.48, fontSize:30, bold:true, color:C.white, fontFace:'Aptos Display', margin:0 });
  s.addText('Teaching LLM Agents When to Think, Reflect, or Seek Knowledge', { x:0.60, y:1.98, w:6.35, h:0.90, fontSize:22, bold:true, color:C.white, breakLine:false, fit:'shrink', margin:0 });
  s.addText('Agentic knowledgeable self-awareness lets agents autonomously regulate knowledge utilization through situational special tokens.', { x:0.64, y:3.13, w:5.75, h:0.54, fontSize:12, color:'CBD5E1', breakLine:false, fit:'shrink', margin:0 });
  addMetric(s, 'Llama-8B ALFWorld All', '84.33%', 6.55, 3.02, 1.35, C.green, '15.01% Know%');
  addMetric(s, 'Gemma-2B ALFWorld All', '79.85%', 8.02, 3.02, 1.35, C.cyan, '26.41% Know%');
  s.addText('Source: arxiv.org/abs/2504.03553', { x:0.64, y:4.86, w:3.0, h:0.14, fontSize:7.5, color:'94A3B8', margin:0 });
  footer(s, 1, 'Technical presentation for ML researchers and graduate students');
}

// Slide 2
{
  const s = pptx.addSlide(); addBg(s); addTitle(s, "Current Agent Training Uses 'Flood Irrigation'", 'Problem framing');
  s.addText('Gold trajectories, external feedback, and domain knowledge are injected regardless of situational need — increasing fragility and inference cost.', { x:0.47, y:1.08, w:8.5, h:0.28, fontSize:10.2, color:C.muted, margin:0, fit:'shrink' });
  const xs = [0.55, 3.55, 6.55];
  const heads = ['Trajectory imitation', 'Trial-and-error refinement', 'Knowledge-augmented planning'];
  const methods = ['ReAct', 'Reflexion', 'KnowAgent / WKM'];
  const fills = [C.blueSoft, C.amberSoft, C.lilac];
  const cols = [C.blue, C.amber, C.purple];
  const limits = [
    ['Pattern-fitting from gold actions', 'Brittle on unexpected inputs'],
    ['External feedback after failures', 'Correction not situation-aware'],
    ['Domain knowledge applied broadly', 'High query and context cost']
  ];
  for (let i=0;i<3;i++) {
    card(s, xs[i], 1.72, 2.72, 2.26, { fill: C.white, line: fills[i] });
    s.addShape(pptx.ShapeType.ellipse, { x:xs[i]+0.18, y:1.94, w:0.44, h:0.44, fill:{color:fills[i]}, line:{color:fills[i]} });
    s.addText(String(i+1), { x:xs[i]+0.18, y:2.05, w:0.44, h:0.08, align:'center', fontSize:10, bold:true, color:cols[i], margin:0 });
    s.addText(heads[i], { x:xs[i]+0.75, y:1.90, w:1.75, h:0.28, fontSize:11.4, bold:true, color:C.ink, fit:'shrink', margin:0 });
    pill(s, methods[i], xs[i]+0.75, 2.35, 1.25, fills[i], cols[i]);
    bulletList(s, limits[i], xs[i]+0.25, 2.80, 2.1, { fontSize:8.2, gap:0.38, dot:cols[i], h:0.22 });
  }
  s.addShape(pptx.ShapeType.chevron, { x:3.0, y:2.55, w:0.28, h:0.50, fill:{color:C.grey}, line:{color:C.grey} });
  s.addShape(pptx.ShapeType.chevron, { x:6.0, y:2.55, w:0.28, h:0.50, fill:{color:C.grey}, line:{color:C.grey} });
  card(s, 1.18, 4.38, 7.6, 0.48, { fill: C.navy, line: C.navy, shadow:false });
  s.addText('KnowSelf target: replace blanket injection with situational self-awareness — act directly, reflect, or retrieve only when needed.', { x:1.42, y:4.54, w:7.1, h:0.10, fontSize:8.2, bold:true, color:C.white, align:'center', margin:0, fit:'shrink' });
  footer(s, 2);
}

// Slide 3
{
  const s = pptx.addSlide(); addBg(s); addTitle(s, 'Three Situational Modes: Fast, Slow, Knowledgeable', 'Decision criterion');
  card(s, 0.55, 1.10, 2.15, 0.72, { fill: C.white, line: C.blueSoft });
