  s.addText('Can reflection\nfix it?', { x:3.73, y:2.59, w:1.38, h:0.28, fontSize:9.4, bold:true, color:C.amber, align:'center', margin:0 });
  arrow(s, 5.50, 2.83, 6.40, 2.83, C.amber);
  pill(s, 'YES', 5.72, 2.48, 0.44, C.amberSoft, C.amber);
  card(s, 6.42, 2.22, 2.75, 0.98, { fill: C.amberSoft, line: C.amber });
  s.addText('Slow Thinking', { x:6.73, y:2.42, w:2.02, h:0.18, fontSize:14, bold:true, color:C.amber, align:'center', margin:0 });
  s.addText('Initial action is wrong, but self-reflection recovers the correct plan.', { x:6.65, y:2.75, w:2.25, h:0.18, fontSize:7.1, color:C.ink, align:'center', margin:0, fit:'shrink' });
  arrow(s, 4.43, 3.21, 4.43, 3.83, C.purple);
