  card(s, 3.07, 3.83, 2.75, 0.98, { fill: C.lilac, line: C.purple });
  s.addText('Knowledgeable Thinking', { x:3.28, y:4.03, w:2.33, h:0.18, fontSize:13.1, bold:true, color:C.purple, align:'center', margin:0, fit:'shrink' });
  s.addText('Neither direct action nor reflection is enough; consult external knowledge.', { x:3.34, y:4.36, w:2.2, h:0.18, fontSize:7.0, color:C.ink, align:'center', margin:0, fit:'shrink' });
